// Generated by Skipo from .skipo/project.json; local values never prove registry authority.
export const appId = '';
export const appRegistrationStatus = 'pending_enrollment' as const;
export const appIdentityAuthorityVerified = false as const;
export const deploymentId: string | null = null;
export const oauthClientId: string | null = null;

export function workspaceEnvironment(env?: Record<string, unknown>) {
  const {
    WORKSPACE_APP_ID: _untrustedAppId,
    SKIPO_DEPLOYMENT_ID: _untrustedDeploymentId,
    LUTH_OAUTH_CLIENT_ID: _untrustedOauthClientId,
    ...safeEnv
  } = env ?? {};
  return {
    ...safeEnv,
    ...(appId ? { WORKSPACE_APP_ID: appId } : {}),
    ...(appIdentityAuthorityVerified && deploymentId ? { SKIPO_DEPLOYMENT_ID: deploymentId } : {}),
    ...(appIdentityAuthorityVerified && oauthClientId ? { LUTH_OAUTH_CLIENT_ID: oauthClientId } : {}),
  };
}
